#!/usr/bin/env python3
"""Hash-bound, fully offline illustrated release notes; no historical test claims."""
from pathlib import Path
import base64,hashlib,html,json
root=Path(__file__).resolve().parents[1];out=root.parent/'deliverables';out.mkdir(exist_ok=True)
version=(root/'VERSION').read_text().strip();iteration=version.rsplit('.',1)[-1]
h=lambda b:hashlib.sha256(b).hexdigest()
capture=json.loads((root/'validation/ui-capture.json').read_text());validation=json.loads((root/f'docs/VALIDATION-{iteration}.json').read_text());probe=json.loads((root/f'validation/iteration-{iteration}/binary-probe.json').read_text())
assert capture['version']==validation['version']==version
for name,digest in capture['assets'].items():assert h((root/name).read_bytes())==digest
for name,digest in capture['screenshots'].items():assert h((root/'validation'/name).read_bytes())==digest
binary_hash=h((root/'artifacts/workbuddy.so').read_bytes());assert probe['result']=='PASS' and probe['binary_sha256']==binary_hash

def figure(name,title,caption,cls=''):
 image='data:image/png;base64,'+base64.b64encode((root/'validation'/name).read_bytes()).decode()
 return f'<figure class="{cls}"><button class="shot" aria-label="放大：{html.escape(title)}"><img src="{image}" alt="{html.escape(title)}；本地模拟后端，非真实账号"><span>点击放大 ↗</span></button><figcaption><b>{html.escape(title)}</b><p>{html.escape(caption)}</p></figcaption></figure>'

first={'official-dashboard-desktop.png':'仪表盘 · 到期与待处理','official-accounts-mobile.png':'账号 · 手机简洁列表','official-tasks-desktop.png':'任务 · 账号优先','official-settings-mobile.png':'设置 · 自动业务与维护'}
labels={'accounts':'账号','dashboard':'仪表盘','models':'模型中心','tasks':'任务','settings':'插件设置','hub-sources':'来源账号账号','hub-filter':'动态来源＋渠道筛选','hub-failure':'模拟失败诊断','hub-detail':'逐来源模型参数','connection-expanded':'仪表盘连接详情','dark':'宿主深色模式','menu-dialog':'宿主菜单与插件弹窗','config-models':'原生模型配置入口','config-settings':'原生插件设置'}
def title(n):
 n=n.removesuffix('.png');prefix='原版CPAMC · ' if n.startswith('official-') else 'CPAMP夹具 · ' if n.startswith('cpamp-') else '独立工作区 · '
 n=n.removeprefix('official-').removeprefix('cpamp-');suffix=' · 手机' if n.endswith('-mobile') else ' · 桌面' if n.endswith('-desktop') else '';n=n.removesuffix('-mobile').removesuffix('-desktop')
 return prefix+labels.get(n,n)+suffix
caption='当前构建的实际截图，业务数据为本地模拟。渠道“动态”是目录返回，“配置”是自定义声明；均不是实际调用验收。'
gallery=''.join(figure(n,t,caption,'mobile' if 'mobile' in n else 'wide')for n,t in first.items())
extras=''.join(figure(n,title(n),caption,'mobile' if 'mobile' in n or 'menu-dialog' in n else 'wide')for n in capture['screenshots'] if n not in first)
